/**
 * Icon markup, drawn from the sprite at /assets/icons.svg.
 *
 * The sprite is generated by scripts/build-icons.js from the Lucide set via
 * Iconify, and is precached by the service worker so icons work offline. Icons
 * inherit the surrounding text colour, so they follow the light/dark theme.
 */

/**
 * An `<svg>` referencing one sprite symbol.
 *
 * Decorative by default — give the surrounding control an aria-label.
 */
export function iconMarkup(id) {
    return `<svg class="icon" aria-hidden="true" focusable="false"><use href="/assets/icons.svg#${id}"></use></svg>`;
}
